import{_ as i,a0 as u,w as p,s as o,I as s,x as a,a1 as l,A as e,ao as b}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Ubuntu 22.04 LTS 中安装经典 GNOME Flashback 指南 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 22.04 LTS 中安装经典 GNOME Flashback 指南 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 22.04 LTS 中安装经典 GNOME Flashback 指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 22.04 LTS 中安装经典 GNOME Flashback 指南 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220501 How to Install Classic GNOME Flashback in Ubuntu 22.04 LTS","title":"Ubuntu 22.04 LTS 中安装经典 GNOME Flashback 指南","tag":"202205","desc":""},"relativePath":"202205/20220501 How to Install Classic GNOME Flashback in Ubuntu 22.04 LTS.md","filePath":"[post].md"}'),r={name:"202205/20220501 How to Install Classic GNOME Flashback in Ubuntu 22.04 LTS.md"};function d(h,t,g,m,k,M){const n=u("Link");return p(),o("div",null,[t[20]||(t[20]=s("h1",{id:"ubuntu-22-04-lts-中安装经典-gnome-flashback-指南",tabindex:"-1"},[a("Ubuntu 22.04 LTS 中安装经典 GNOME Flashback 指南 "),s("a",{class:"header-anchor",href:"#ubuntu-22-04-lts-中安装经典-gnome-flashback-指南","aria-label":"Permalink to “Ubuntu 22.04 LTS 中安装经典 GNOME Flashback 指南”"},"​")],-1)),t[21]||(t[21]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202205/23/151318xi8c3qipphg8xz0i.jpg",alt:""})],-1)),t[22]||(t[22]=s("blockquote",null,[s("p",null,"关于如何在最新的 UBUNTU 22.04 LTS 中安装旧的经典 GNOME Flashback 的快速指南。")],-1)),s("p",null,[l(n,{href:"https://wiki.archlinux.org/index.php/GNOME/Flashback"},{default:e(()=>[...t[0]||(t[0]=[a("GNOME Flashback",-1)])]),_:1}),t[1]||(t[1]=a("（又名 classic GNOME）是旧 GNOME 3 shell 的一个分支，它使用早期 GNOME 2 技术的布局和原则。它的速度快如闪电，并且在设计上非常轻量级。因此，它非常适合几十年前的老旧硬件。",-1))]),s("p",null,[t[3]||(t[3]=a("随着带有现代 GNOME 42 的 ",-1)),l(n,{href:"https://www.debugpoint.com/2022/01/ubuntu-22-04-lts/"},{default:e(()=>[...t[2]||(t[2]=[a("Ubuntu 22.04 LTS",-1)])]),_:1}),t[4]||(t[4]=a(" 的发布，有必要寻找轻量级的桌面环境选项。",-1))]),t[23]||(t[23]=b(`<p>此外，GNOME Flashback 很容易安装在现代 Ubuntu Linux 中，你仍然可以享受 Ubuntu 性能而不必关心 GNOME 42、GTK4、libadwaita 之类的东西。</p><h3 id="在-ubuntu-22-04-lts-中下载并安装经典-gnome-flashback" tabindex="-1">在 Ubuntu 22.04 LTS 中下载并安装经典 GNOME Flashback <a class="header-anchor" href="#在-ubuntu-22-04-lts-中下载并安装经典-gnome-flashback" aria-label="Permalink to “在 Ubuntu 22.04 LTS 中下载并安装经典 GNOME Flashback”">​</a></h3><p>按照以下步骤在 Ubuntu 22.04 LTS 中下载并安装经典 GNOME Flashback（Metacity）。</p><p>在 Ubuntu 22.04 LTS 中打开终端（CTRL+ALT+T）并运行以下命令。安装大小约为 61MB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install gnome-session-flashback</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/05/Install-GNOME-Classic-Flashback-Metacity-in-Ubuntu-22.04-LTS.jpg" alt="Install GNOME Classic Flashback Metacity in Ubuntu 22.04 LTS"></p><p>最后，安装完成后，退出。重新登录时，在登录选项中使用经典的 GNOME Flashback（Metacity） 。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/05/Choose-GNOME-Classic-while-loggin-in.jpg" alt="Choose GNOME Classic while logging in"></p><h3 id="经典-gnome-flashback-的特点" tabindex="-1">经典 GNOME Flashback 的特点 <a class="header-anchor" href="#经典-gnome-flashback-的特点" aria-label="Permalink to “经典 GNOME Flashback 的特点”">​</a></h3><p>首先，当你登录时，你将体验到传统的 GNOME 技术，它已被证明具有良好的生产力，并且比今天的技术快得多。</p><p>在顶部有旧版的面板，左侧是应用菜单，而系统托盘位于桌面的右上方。应用程序菜单显示所有已安装的应用和软件快捷方式，你可以在工作流程中轻松浏览。</p><p>此外，在右侧部分，系统托盘具有默认小部件，例如网络、音量控制、日期和时间以及关机菜单。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/05/Classic-GNOME-Flashback-Metacity-in-Ubuntu-22.04-LTS.jpg" alt="Classic GNOME Flashback Metacity in Ubuntu 22.04 LTS"></p><p>底部面板包含打开的窗口和工作区切换器的应用列表。默认情况下，它为你提供四个工作区供你使用。</p><p>此外，你可以随时更改顶部面板的设置以自动隐藏、调整面板大小和背景颜色。</p><p>除此之外，你可以通过 <code>ALT + 右键点击</code> 顶部面板添加任意数量的旧版小程序。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/04/Panel-Context-Menu.png" alt="Panel Context Menu"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/04/Add-to-panel-widgets.png" alt="Add to panel widgets"></p><h3 id="经典-gnome-的性能" tabindex="-1">经典 GNOME 的性能 <a class="header-anchor" href="#经典-gnome-的性能" aria-label="Permalink to “经典 GNOME 的性能”">​</a></h3><p>首先，磁盘空间占用极小，仅安装 61 MB。我的测试使用了大约 28% 的内存，其中大部分被其他进程占用。猜猜是谁？是的，是 snap-store（又名 Ubuntu 软件）。</p><p>因此，总体而言，它非常轻巧，内存（仅 28 MB）和 CPU（0.1%）占用空间非常小。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/05/Performance-of-GNOME-Classic-in-Ubuntu-22.04.jpg" alt="Performance of GNOME Classic in Ubuntu 22.04"></p><p>此外，假设你将其与同样使用相同技术的 Ubuntu MATE 进行比较。在这种情况下，它比 MATE 更轻量，因为你不需要任何额外的 MATE 应用及其用于通知、主题和其他附加资源的软件包。</p><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to “结束语”">​</a></h3><p>我希望本指南在你决定在 Ubuntu 22.04 LTS Jammy Jellyfish 中安装经典 GNOME 之前帮助你获得必要的信息。</p><hr>`,26)),s("p",null,[t[6]||(t[6]=a("via: ",-1)),l(n,{href:"https://www.debugpoint.com/2022/05/gnome-classic-ubuntu-22-04/"},{default:e(()=>[...t[5]||(t[5]=[a("https://www.debugpoint.com/2022/05/gnome-classic-ubuntu-22-04/",-1)])]),_:1})]),s("p",null,[t[11]||(t[11]=a("作者：",-1)),l(n,{href:"https://www.debugpoint.com/author/admin1/"},{default:e(()=>[...t[7]||(t[7]=[a("Arindam",-1)])]),_:1}),t[12]||(t[12]=a(" 选题：",-1)),l(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[8]||(t[8]=[a("lujun9972",-1)])]),_:1}),t[13]||(t[13]=a(" 译者：",-1)),l(n,{href:"https://github.com/geekpi"},{default:e(()=>[...t[9]||(t[9]=[a("geekpi",-1)])]),_:1}),t[14]||(t[14]=a(" 校对：",-1)),l(n,{href:"https://github.com/turbokernel"},{default:e(()=>[...t[10]||(t[10]=[a("turbokernel",-1)])]),_:1})]),s("p",null,[t[17]||(t[17]=a("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[15]||(t[15]=[a("LCTT",-1)])]),_:1}),t[18]||(t[18]=a(" 原创编译，",-1)),l(n,{href:"https://linux.cn/"},{default:e(()=>[...t[16]||(t[16]=[a("Linux中国",-1)])]),_:1}),t[19]||(t[19]=a(" 荣誉推出",-1))])])}const N=i(r,[["render",d]]);export{f as __pageData,N as default};
